//! 🧪️ Owned serde_json witnesses independently check the borrowed publication oracle.
use super::*;
use crate::snapshot::LayoutSnapshot;
use semio_framework_value::retained_clone::RetainedCloneSource;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:64}}
fn decode(value:&serde_json::Value)->LayoutSnapshot{semio_framework_pack_json::from_json_str(&value.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn close(cursor:&mut LayoutValidationCursor,source:&mut RetainedCloneSource<LayoutSnapshot>)->(usize,usize){cursor.begin_close();let mut bytes=0;let mut turns=0;while !cursor.terminal_is_empty(){let p=cursor.close_step(grant()).unwrap().progress();assert!(p.fits(grant()));bytes+=p.released_bytes;turns+=1;assert!(turns<10000)}while !source.terminal_is_empty(){source.close_step(grant()).unwrap();turns+=1;assert!(turns<10000)}(bytes,turns)}
#[test]
fn neutral_graph_laws_match_the_owned_test_only_oracle(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/✅️validation/🔣️.json")).unwrap();for case in corpus["documents"].as_array().unwrap(){let mut value=corpus["base"].clone();for patch in case["patch"].as_array().unwrap(){*value.pointer_mut(patch["path"].as_str().unwrap()).unwrap()=patch["value"].clone()}let document=decode(&value);let expected=crate::validation::validate_document(&document).is_ok();assert_eq!(expected,case["valid"].as_bool().unwrap());let(mut source,_)=RetainedCloneSource::admit_owned(document,(),grant()).unwrap_or_else(|_|panic!("original source admission failed"));let mut cursor=LayoutValidationCursor::new();let mut capacity=0;let mut done=false;for _ in 0..1000000{for denied in [Default::default(),RetainedCloneGrant{maximum_copy_bytes:0,..grant()},RetainedCloneGrant{maximum_depth:0,..grant()},RetainedCloneGrant{maximum_items:0,..grant()}]{let zero=cursor.advance(source.borrow(),denied.maximum_copy_bytes,denied).unwrap();assert_eq!(zero.progress,Default::default());}let turn=cursor.advance(source.borrow(),grant().maximum_copy_bytes,grant()).unwrap();assert!(turn.progress.fits(grant()));capacity+=turn.progress.retained_capacity_bytes;if turn.done{assert_eq!(turn.error.is_none(),expected,"{}",case["name"]);done=true;break}}assert!(done);assert_eq!(close(&mut cursor,&mut source).0,capacity)}}
#[test]
fn exact_original_identity_and_cancellation_remain_paired(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/✅️validation/🔣️.json")).unwrap();for cancel in [0,1,2,3,10,100]{let(mut source,_)=RetainedCloneSource::admit_owned(decode(&corpus["base"]),(),grant()).unwrap_or_else(|_|panic!("original admission"));let(mut swapped,_)=RetainedCloneSource::admit_owned(decode(&corpus["base"]),(),grant()).unwrap_or_else(|_|panic!("second original admission"));let mut cursor=LayoutValidationCursor::new();let mut capacity=0;for _ in 0..cancel{capacity+=cursor.advance(source.borrow(),grant().maximum_copy_bytes,grant()).unwrap().progress.retained_capacity_bytes}if cancel>0{assert!(cursor.demand(swapped.borrow(),grant().maximum_copy_bytes).is_err());assert!(cursor.demand(source.borrow().project(1,|value|value),grant().maximum_copy_bytes).is_err());}assert_eq!(close(&mut cursor,&mut source).0,capacity);while !swapped.terminal_is_empty(){swapped.close_step(grant()).unwrap();}}}
